mapper.select:
select co.id as orderId, co.status as orderStatus, cb.org_id as orgName, DATE_FORMAT( cb.crt_time, '%Y-%m-%d' ) as billDate, cb.crt_id as operateName, co.order_record_num as orderNumber, cb.receivable_amount, sum(cd.amount) as receivedAmount, group_concat(DISTINCT cd.account_item_name) as accountTypeName from coupon_bill cb inner join coupon_order co on cb.order_record_id = co.id inner join coupon_bill_pay_detail cd on cb.id = cd.bill_id where co.inservice = 1 and cb.patient_id = #{query.patientId}
and cb.org_id in
#{item}
and (`cb`.`crt_time` >= #{query.soldStartDate} and `cb`.`crt_time` < DATE_ADD(#{query.soldStartDate} ,INTERVAL '1' DAY))
group by cb.order_record_id, cb.org_id, cb.crt_id
